// Service worker for บ้านรอดไหม? — generated by tools/build.mjs, do not
// edit public/sw.js by hand. Offline after the first visit:
//   pages      network first (3 s), then the cached app shell
//   content    network first (2.5 s), so safety fixes reach people fast
//   everything else: cached, refreshed in the background
// iOS in-app browsers (LINE, Facebook...) don't run service workers; the
// game simply works online there.

const VERSION = '410e54721e';
const PRECACHE = [
  "/",
  "/css/app.css",
  "/js/analytics.js",
  "/js/audio.js",
  "/js/cards.js",
  "/js/content.js",
  "/js/fx.js",
  "/js/house.js",
  "/js/icons.js",
  "/js/main.js",
  "/js/mascot.js",
  "/js/progress.js",
  "/js/rng.js",
  "/js/round.js",
  "/js/run.js",
  "/js/scene.js",
  "/js/share.js",
  "/js/svgdraw.js",
  "/js/ui.js",
  "/js/util.js",
  "/content/checklists.json",
  "/content/config.json",
  "/content/helplines.json",
  "/content/items.json",
  "/content/rooms.json",
  "/content/sources.json",
  "/content/strings.json",
  "/art/sprites.svg",
  "/art/rooms/front.svg",
  "/art/rooms/living.svg",
  "/art/rooms/kitchen.svg",
  "/fonts/kanit-latin-400.woff2",
  "/fonts/kanit-latin-600.woff2",
  "/fonts/kanit-thai-400.woff2",
  "/fonts/kanit-thai-600.woff2",
  "/manifest.webmanifest",
  "/icons/icon.svg"
];
const CACHE = `brm-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.all(PRECACHE.map(async (url) => {
      try {
        const res = await fetch(new Request(url, { cache: 'reload' }));
        if (res.ok && !res.redirected) await cache.put(url, res);
      } catch { /* offline during install: the file is fetched later */ }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('brm-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return;
  if (req.mode === 'navigate') {
    event.respondWith(networkFirst(req, 3000, '/'));
  } else if (url.pathname.startsWith('/content/')) {
    event.respondWith(networkFirst(req, 2500, null));
  } else {
    event.respondWith(staleWhileRevalidate(event, req));
  }
});

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms));
}

async function networkFirst(req, ms, fallback) {
  const cache = await caches.open(CACHE);
  const key = new URL(req.url).pathname;
  try {
    const res = await Promise.race([fetch(req), timeout(ms)]);
    if (res.ok && !res.redirected) cache.put(key, res.clone());
    return res;
  } catch {
    const hit = (await cache.match(key)) || (await cache.match(req, { ignoreSearch: true }));
    if (hit) return hit;
    if (fallback) {
      const shell = await cache.match(fallback);
      if (shell) return shell;
    }
    return new Response('offline', { status: 503, headers: { 'content-type': 'text/plain' } });
  }
}

async function staleWhileRevalidate(event, req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req, { ignoreSearch: true });
  const update = fetch(req).then((res) => {
    if (res.ok && !res.redirected) cache.put(req, res.clone());
    return res;
  }).catch(() => null);
  if (hit) {
    event.waitUntil(update);
    return hit;
  }
  return (await update) || new Response('', { status: 504 });
}
